"""Balanced option rows and combined written/circle answers preserve scan geometry."""
from pathlib import Path
exec(Path('tests/cbse-mcq-browser.py').read_text().split("\nwith fx['ns']['sync_playwright']() as p:")[0])
with fx['ns']['sync_playwright']() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=b.new_context(viewport={'width':1280,'height':1000});ctx.route('https://www.gstatic.com/firebasejs/**',mcq_sdk);page=ctx.new_page();page.route('**/api/staff-access',lambda route:mcq_api(page,route));page.goto('http://127.0.0.1:8000/cbse-mission.html#tab=mcq');page.locator('.mcq-entry-form').wait_for()
 result=page.evaluate("""async()=>{const {buildMCQPaperFrame}=await import('./cbse-mcq-page-render.js'),{answerStripSVG}=await import('./cbse-mcq-print.js'),{scanResponsePhoto,bubblePoint}=await import('./cbse-mcq-scan.js');const options=[['R/2','2R','4R','R/4'],['A medium length option with a few words','Short','Short','Short'],['A long option with substantial explanatory text '.repeat(5),'Short','Short','Short']],questions=options.map((choices,i)=>({id:'QS00'+(i+1),stem:'Question '+(i+1),options:choices,topic:'Contributor topic',contributorName:i?'Teacher B':'Teacher A'}));const paper=await buildMCQPaperFrame({id:'QPS123',classId:'X',subjectName:'Science',createdByName:'Paper creator',count:3,questions},{}),doc=paper.frame.contentDocument,columns=[...doc.querySelectorAll('.mcq-options')].map(n=>n.dataset.optionColumns),writingLines=doc.querySelectorAll('.response-area svg line').length,standalone=doc.querySelectorAll('.mcq-written-answer-area').length,credits=doc.querySelector('.paper-contributors').textContent;paper.frame.remove();const scans=[];for(const count of [4,20]){const svg=answerStripSVG(count,0,true,true),image=new Image();image.src='data:image/svg+xml;base64,'+btoa(new XMLSerializer().serializeToString(svg));await image.decode();const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=Number(svg.viewBox.baseVal.height);const g=canvas.getContext('2d');g.fillStyle='white';g.fillRect(0,0,canvas.width,canvas.height);g.drawImage(image,0,0,canvas.width,canvas.height);g.fillStyle='black';g.font='18px Arial';for(let i=0;i<count;i++){const point=bubblePoint(i,1);g.fillText('B',106+(i>=10?500:0),point.y+4);g.beginPath();g.arc(point.x,point.y,9,0,Math.PI*2);g.fill();}scans.push(scanResponsePhoto(canvas,count,{compact:true}).responses);}return {columns,writingLines,standalone,credits,scans};}""")
 assert result['columns']==['4','2','1'],result;assert result['writingLines']==3;assert result['standalone']==0;assert result['credits']=='Contributors: Teacher A · Teacher B';assert result['scans']==[['B']*4,['B']*20],result;b.close()
